+import { Pool } from "pg";
+import { writeFileSync, mkdirSync } from "fs";
+import { dirname } from "path";
+
+const pool = new Pool({ connectionString: process.env.DATABASE_URL });
+
+interface Column {
+  name: string;
+  type: string;
+  is_nullable: boolean;
+}
+
+interface Table {
+  name: string;
+  columns: Column[];
+}
+
+async function fetchSchema(): Promise<Table[]> {
+  const tablesResult = await pool.query(`
+    SELECT table_name
+    FROM information_schema.tables
+    WHERE table_schema = 'public'
+    ORDER BY table_name
+  `);
+
+  const tables: Table[] = [];
+
+  for (const { table_name } of tablesResult.rows) {
+    const columnsResult = await pool.query(`
+      SELECT
+        column_name as name,
+        udt_name as type,
+        is_nullable = 'YES' as is_nullable
+      FROM information_schema.columns
+      WHERE table_schema = 'public' AND table_name = $1
+      ORDER BY ordinal_position
+    `, [table_name]);
+
+    tables.push({
+      name: table_name,
+      columns: columnsResult.rows.map(row => ({
+        name: row.name,
+        type: mapPostgresType(row.type),
+        is_nullable: row.is_nullable,
+      })),
+    });
+  }
+
+  await pool.end();
+  return tables;
+}
+
+function mapPostgresType(pgType: string): string {
+  const typeMap: Record<string, string> = {
+    int4: "number",
+    int8: "number",
+    float4: "number",
+    float8: "number",
+    text: "string",
+    varchar: "string",
+    char: "string",
+    bool: "boolean",
+    timestamp: "Date",
+    timestamptz: "Date",
+    date: "Date",
+    uuid: "string",
+    json: "unknown",
+    jsonb: "unknown",
+  };
+  return typeMap[pgType] || "unknown";
+}
+
+function generateTypeFile(tables: Table[]): string {
+  let output = `// AUTO-GENERATED FROM DATABASE SCHEMA - DO NOT EDIT MANUALLY
+// Run: npm run generate-db-types
+
+`;
+
+  for (const table of tables) {
+    const interfaceName = toPascalCase(table.name);
+    output += `export interface ${interfaceName} {\n`;
+
+    for (const col of table.columns) {
+      const typeDef = col.is_nullable ? `${col.type} | null` : col.type;
+      output += `  ${col.name}: ${typeDef};\n`;
+    }
+
+    output += `}\n\n`;
+  }
+
+  return output;
+}
+
+function toPascalCase(str: string): string {
+  return str
+    .split("_")
+    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
+    .join("");
+}
+
+async function main() {
+  try {
+    console.log("Connecting to database and fetching schema...");
+    const tables = await fetchSchema();
+
+    console.log(`Found ${tables.length} tables`);
+
+    const typeFile = generateTypeFile(tables);
+    const outputPath = "src/db/types.generated.ts";
+
+    mkdirSync(dirname(outputPath), { recursive: true });
+    writeFileSync(outputPath, typeFile);
+
+    console.log(`✓ Generated ${outputPath}`);
+  } catch (error) {
+    console.error("Failed to generate types:", error);
+    process.exit(1);
+  }
+}
+
+main();
