@@ -0,0 +1,167 @@
+import { readFileSync, readdirSync } from "fs";
+import { join } from "path";
+
+interface GeneratedType {
+  [field: string]: string;
+}
+
+interface Schema {
+  [table: string]: GeneratedType;
+}
+
+function parseGeneratedTypes(): Schema {
+  const typeFile = readFileSync("src/db/types.generated.ts", "utf-8");
+  const schema: Schema = {};
+
+  const typeMatches = typeFile.matchAll(
+    /export interface (\w+) \{([^}]+)\}/g,
+  );
+
+  for (const match of typeMatches) {
+    const tableName = match[1].toLowerCase();
+    const fieldsStr = match[2];
+    const fields: GeneratedType = {};
+
+    const fieldMatches = fieldsStr.matchAll(/(\w+):\s*([^;]+);/g);
+    for (const fieldMatch of fieldMatches) {
+      fields[fieldMatch[1]] = fieldMatch[2].trim();
+    }
+
+    schema[tableName] = fields;
+  }
+
+  return schema;
+}
+
+function extractSelectColumns(sql: string): Map<string, string[]> {
+  const result = new Map<string, string[]>();
+
+  const selectMatches = sql.matchAll(
+    /SELECT\s+([^F]+?)\s+FROM\s+(\w+)/gi,
+  );
+
+  for (const match of selectMatches) {
+    const columns = match[1]
+      .split(",")
+      .map(col => col.trim())
+      .filter(col => col !== "*")
+      .map(col => col.split(" ").pop() || col);
+
+    const table = match[2].toLowerCase();
+    result.set(table, columns);
+  }
+
+  return result;
+}
+
+function extractInsertColumns(sql: string): Map<string, string[]> {
+  const result = new Map<string, string[]>();
+
+  const insertMatches = sql.matchAll(
+    /INSERT\s+INTO\s+(\w+)\s*\(([^)]+)\)/gi,
+  );
+
+  for (const match of insertMatches) {
+    const table = match[1].toLowerCase();
+    const columns = match[2]
+      .split(",")
+      .map(col => col.trim());
+
+    result.set(table, columns);
+  }
+
+  return result;
+}
+
+async function validateQueryFile(
+  filePath: string,
+  schema: Schema,
+): Promise<string[]> {
+  const content = readFileSync(filePath, "utf-8");
+  const errors: string[] = [];
+
+  const queryMatches = content.matchAll(
+    /pool\.query\s*\(\s*"([^"]+)"/g,
+  );
+
+  for (const match of queryMatches) {
+    const sql = match[1];
+
+    const selectCols = extractSelectColumns(sql);
+    for (const [table, cols] of selectCols) {
+      if (!(table in schema)) {
+        errors.push(
+          `${filePath}: Unknown table '${table}' in query: SELECT ... FROM ${table}`,
+        );
+        continue;
+      }
+
+      for (const col of cols) {
+        if (!(col in schema[table])) {
+          errors.push(
+            `${filePath}: Unknown column '${col}' in table '${table}'`,
+          );
+        }
+      }
+    }
+
+    const insertCols = extractInsertColumns(sql);
+    for (const [table, cols] of insertCols) {
+      if (!(table in schema)) {
+        errors.push(
+          `${filePath}: Unknown table '${table}' in INSERT query`,
+        );
+        continue;
+      }
+
+      for (const col of cols) {
+        if (!(col in schema[table])) {
+          errors.push(
+            `${filePath}: Unknown column '${col}' in table '${table}'`,
+          );
+        }
+      }
+    }
+  }
+
+  return errors;
+}
+
+async function main() {
+  try {
+    console.log("Validating database queries against generated schema...");
+
+    const schema = parseGeneratedTypes();
+    console.log(`Loaded schema for tables: ${Object.keys(schema).join(", ")}`);
+
+    const dbDir = "src/db";
+    const files = readdirSync(dbDir)
+      .filter(f => f.endsWith(".ts") && !f.endsWith(".generated.ts"))
+      .map(f => join(dbDir, f));
+
+    let totalErrors = 0;
+    for (const file of files) {
+      const errors = await validateQueryFile(file, schema);
+      totalErrors += errors.length;
+
+      if (errors.length > 0) {
+        console.error(`\n✗ ${file}:`);
+        errors.forEach(e => console.error(`  ${e}`));
+      }
+    }
+
+    if (totalErrors === 0) {
+      console.log("\n✓ All queries validated successfully");
+    } else {
+      console.error(
+        `\n✗ Found ${totalErrors} validation error(s)`,
+      );
+      process.exit(1);
+    }
+  } catch (error) {
+    console.error("Validation failed:", error);
+    process.exit(1);
+  }
+}
+
+main();
