+import { pool } from "./pool.ts";
+import type * as Schema from "./types.generated.ts";
+
+type TableKey = keyof typeof Schema;
+type TableType<T extends TableKey> = (typeof Schema)[T][];
+
+export async function query<T extends TableKey>(
+  sql: string,
+  params: unknown[],
+): Promise<T[]> {
+  const result = await pool.query(sql, params);
+  return result.rows;
+}
+
+export async function queryOne<T extends TableKey>(
+  sql: string,
+  params: unknown[],
+): Promise<T | null> {
+  const result = await pool.query(sql, params);
+  return result.rows[0] ?? null;
+}
+
+export async function execute(sql: string, params: unknown[]): Promise<void> {
+  await pool.query(sql, params);
+}
